```python
import torch
import torch.nn.functional as F
from torch_geometric.nn import HeteroConv, GCNConv, SAGEConv

class HeteroSDM(torch.nn.Module):
    def __init__(self, species_dim=64, loc_dim=128, num_env_vars=19):
        super().__init__()
        self.species_lin = torch.nn.Linear(species_dim, 64)
        self.loc_lin = torch.nn.Linear(num_env_vars + 2, 64)  # env vars + coords

        self.conv1 = HeteroConv({
            ('location', 'detected', 'species'): SAGEConv((64, 64), 128),
            ('species', 'rev_detected', 'location'): SAGEConv((64, 64), 128),
        }, aggr='sum')

        self.conv2 = HeteroConv({
            ('location', 'detected', 'species'): SAGEConv((128, 128), 64),
            ('species', 'rev_detected', 'location'): SAGEConv((128, 128), 64),
        }, aggr='sum')

        self.classifier = torch.nn.Linear(64 + 64, 1)

    def forward(self, x_dict, edge_index_dict):
        x_dict['species'] = self.species_lin(x_dict['species'])
        x_dict['location'] = self.loc_lin(x_dict['location'])
        x_dict = self.conv1(x_dict, edge_index_dict)
        x_dict = {k: F.relu(v) for k, v in x_dict.items()}
        x_dict = self.conv2(x_dict, edge_index_dict)
        return x_dict

    def predict_edge(self, loc_emb, sp_emb):
        return torch.sigmoid(self.classifier(torch.cat([loc_emb, sp_emb], dim=-1)))
```

