library(geometry)

convex_hull_fric <- function(traits, community) {
  pca_result <- prcomp(traits, scale. = TRUE)
  scores <- pca_result$x[, 1:4]
  fric_values <- sapply(1:ncol(community), function(j) {
    species_present <- which(community[, j] > 0)
    if(length(species_present) <= 4) return(0)
    hull <- convhulln(scores[species_present, ], options = 'FA')
    return(hull$vol)
  })
  list(FRic = fric_values, PCA = pca_result)
}
```

