library(R2jags)

data_augmentation_richness <- function(detection_matrix, M_augment = 100) {
  model_string <- 'model {
    omega ~ dbeta(1, 1)
    for(i in 1:(n+M)) {
      w[i] ~ dbern(omega)
      for(j in 1:J) {
        logit(p[i,j]) <- alpha[j]
        y[i,j] ~ dbern(w[i] * p[i,j])
      }
    }
    for(j in 1:J) { alpha[j] ~ dnorm(0, 0.01) }
    richness <- sum(w[])
  }'
  n <- nrow(detection_matrix)
  M <- M_augment
  data <- list(y = rbind(detection_matrix, matrix(0, M, ncol(detection_matrix))),
    n = n, M = M, J = ncol(detection_matrix))
  params <- c('omega', 'richness')
  result <- jags(data, inits = NULL, params, model_string,
    n.chains = 3, n.iter = 5000)
  result
}
```

