  int<lower=0> y[T];
  vector[T] temperature;
}
parameters {
  real<lower=0> r;
  real<lower=0> K;
  real beta;
  real<lower=0> sigma_proc;
  real<lower=0> sigma_obs;
  vector[T] logN;
}
model {
  r ~ normal(0, 1);
  K ~ lognormal(5, 1);
  beta ~ normal(0, 0.5);
  sigma_proc ~ exponential(1);
  sigma_obs ~ exponential(1);
  logN[1] ~ normal(5, 1);
  for (t in 2:T) {
    logN[t] ~ normal(logN[t-1] + r * (1 - exp(logN[t-1]) / K) + beta * temperature[t], sigma_proc);
  }
  for (t in 1:T) {
    y[t] ~ poisson_log(logN[t]);
  }
}
