[CODE]
```python
hill_numbers <- function(abundances, q_values = c(0, 1, 2)) {
  p <- abundances / sum(abundances)
  p <- p[p > 0]
  sapply(q_values, function(q) {
    if (q == 1) exp(-sum(p * log(p)))
    else if (q == Inf) 1 / max(p)
    else sum(p^q)^(1 / (1 - q))
  })
}
```

